// dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_rowCopy
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "__rb0", fn: function () { return "담당자의 확인 후 최종 임시비밀번호와 비밀번호변경코드를 E-Mail(" + String(String(((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : "")(dma_pageContext.get("apctEmail")))) + ")로 보내드립니다."; } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { console.warn("[sdd] 행 복사 대상 부재: " + it.childId); continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

// as-is 흐름 보존 — 스켈레톤이 대체한 함수가 쓰던 전역 선언
scwin.sub_apctDd_Y = undefined; scwin.sub_apctDd_M = undefined; scwin.sub_apctDd_D = undefined;

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_rowCopy();
        await scwin.init_conds();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldfil40401.onpageload' });
    }
};


///////// 3. 컴포넌트 이벤트 영역 /////////

/**
 * @event
 * @name scwin.btn_Print_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.btn_Print_onclick = function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin btn_Print_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        scwin.print('' + dma_pageContext.get("apctId") + '')
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil40401.btn_Print_onclick' }); }
};


///////// 4. 서브미션 콜백 영역 /////////

/**
 * @method
 * @name scwin.tx_fn_Print
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_Print = async function () {
    try { return await $c.data.downFile("/common/newPrint.do", "", ($c.util.getComponent("dma_PrintReq") ? $c.util.getComponent("dma_PrintReq").getJSON() : {})); } catch (_e) { await $c.exception.handleError(_e, { context: '다운로드' }); return null; }
};


///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.print
 * @author Inswave
 * @date 2026. 09. 29
 * @param _apctId
 * @returns
 * @hidden N
*/
scwin.print = function (_apctId) {
    /* sdd-asis-lifecycle:begin fn_Print — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const rexName = (String((((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "rexName" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("rexName"))) == null ? '' : (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "rexName" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("rexName")))).indexOf('$' + '{') >= 0 ? '' : String((((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "rexName" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("rexName"))) == null ? '' : (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "rexName" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("rexName")))));
    if (rexName === '') {
        return;
    }
    const dataLocation = "/outer/reportPrint.do?method=passwordReissuanceNewReport&apctId=" + _apctId;
    $.ajax({ type: "POST", async: false, url: dataLocation, data: {  }, success: async function(data) {
                const result = (typeof data === "string" ? (typeof data === "string" ? JSON.parse(data) : data) : data);
                const form = (document.newReportForm || { elements: [] });
                $c.util.getComponent('dma_PrintReq').set('nisurCd', result.isurCd);
                $c.util.getComponent('dma_PrintReq').set('ncorpNm', result.corpNm);
                $c.util.getComponent('dma_PrintReq').set('ncorpRegNo', result.corpRegNo);
                $c.util.getComponent('dma_PrintReq').set('nbzRegNo', result.bzRegNo);
                $c.util.getComponent('dma_PrintReq').set('nrepNm', result.repNm);
                $c.util.getComponent('dma_PrintReq').set('nhpage', result.hpage);
                $c.util.getComponent('dma_PrintReq').set('nlocAddr', result.locAddr);
                $c.util.getComponent('dma_PrintReq').set('nlocZipcd', result.locZipcd);
                $c.util.getComponent('dma_PrintReq').set('napctNm', result.apctNm);
                $c.util.getComponent('dma_PrintReq').set('napctTelNo', result.apctTelNo);
                $c.util.getComponent('dma_PrintReq').set('napctFaxNo', result.apctFaxNo);
                $c.util.getComponent('dma_PrintReq').set('napctEmail', result.apctEmail);
                $c.util.getComponent('dma_PrintReq').set('nreisuRsn', result.reisuRsn);
                $c.util.getComponent('dma_PrintReq').set('nTempleteCd', rexName);
                if (result.apctDd) {
                    const sub_apctDd = result.apctDd;
                    scwin.sub_apctDd_Y = sub_apctDd.substring(0, 4);
                    scwin.sub_apctDd_M = sub_apctDd.substring(4, 6);
                    scwin.sub_apctDd_D = sub_apctDd.substring(6, 8);
                    $c.util.getComponent('dma_PrintReq').set('napctDd', scwin.sub_apctDd_Y + "년 " + scwin.sub_apctDd_M + "월 " + scwin.sub_apctDd_D + "일");
                } else {
                    $c.util.getComponent('dma_PrintReq').set('napctDd', result.apctDd);
                }
                await scwin.tx_fn_Print();
            }, error: async function(request, status, error) {
                await $c.win.alert("장애발생.");
                return;
            }, complete: function() {

            } });
    /* sdd-asis-lifecycle:end */
};
